"""Tests for agent/ and run.py, on clips generated by agent/demo.py.
Run from the repo root: pytest tests/test_agent.py"""
import json
import shutil
import threading
import urllib.request
from http.server import HTTPServer

import pytest

from agent import core, demo, reason, samples
from evals.score import load_cases, score_all
import run


@pytest.fixture
def env(tmp_path, monkeypatch):
    root = demo.make(tmp_path / "samples")
    monkeypatch.setattr(samples, "SAMPLES_DIR", root)
    monkeypatch.setattr(reason, "CACHE", tmp_path / "nemotron_cache.json")
    monkeypatch.delenv("EVIDENCE_DATABASE_URL", raising=False)
    monkeypatch.delenv("SAMPLE_MODE", raising=False)
    return tmp_path


def no_model(monkeypatch):
    def down(*a, **k):
        raise ConnectionError("Nightshift is not running")
    monkeypatch.setattr(reason.nightshift, "chat", down)


def fake_model(monkeypatch, answers, calls):
    """answers: step -> dict the model replies with (as JSON text)."""
    def chat(messages, step=None, **k):
        calls.append(step)
        return json.dumps(answers.get(step, {})), {"model": "nvidia/nemotron-3.5-lightning-30b-a3b"}
    monkeypatch.setattr(reason.nightshift, "chat", chat)


def test_all_cases_score_100_without_the_model(env, monkeypatch):
    no_model(monkeypatch)
    log = env / "run.jsonl"
    for case in load_cases("evals/cases").values():
        core.run_case(case, sample_mode=False, log_path=log)
    report = score_all(load_cases("evals/cases"), [json.loads(l) for l in log.read_text().splitlines()])
    assert report["mean_score"] == 100.0, json.dumps(report, indent=1)
    lines = [json.loads(l) for l in log.read_text().splitlines()]
    assert [l["step"] for l in lines[:5]] == ["classify", "plan", "run", "verify", "report"]
    assert all(l["sql"] for l in lines if l["step"] in ("classify", "plan", "run", "verify"))
    assert lines[0]["model"]["note"].startswith("model unavailable")


def test_flame_ruling_protects_the_flame(env, monkeypatch):
    no_model(monkeypatch)
    out = core.run_case(json.load(open("evals/cases/case02_lantern_flame.json")), False, env / "r.jsonl")
    plan = next(l for l in out["trace"] if l["step"] == "plan")
    assert plan["decision"]["rulings"] == ["practical_flames_hot"]
    assert plan["decision"]["protect"] == ["lantern_flame"]
    assert "hmem:practical_flames_hot" in plan["cites"]
    verify = next(l for l in out["trace"] if l["step"] == "verify")
    kept = [c for c in verify["decision"]["checks"] if c["check"].startswith("ruling kept")]
    assert kept and kept[0]["passed"]


def test_model_is_checked_against_the_evidence(env, monkeypatch):
    calls = []
    fake_model(monkeypatch, {
        "classify": {"items": ["car", "sky", "dragon"], "clipped_items": ["sky", "dragon"], "why": "sky clipped"},
        # SAM before expand breaks the brief's hard rule
        "plan": {"passes": ["sam_items", "expand_hdr", "to_aces_linear", "balance", "write_exr"],
                 "rulings": ["made_up"], "why": "split first"},
        "report": {"summary": "Recovered the sky."},
    }, calls)
    out = core.run_case(json.load(open("evals/cases/case01_car_sky.json")), False, env / "r.jsonl")
    t = {l["step"]: l for l in out["trace"]}
    assert "dragon" not in t["classify"]["decision"]["items"]
    assert "no measured row" in t["classify"]["why"]
    assert t["classify"]["decision"]["clipped_items"] == ["road", "sky"]  # road kept by threshold
    assert t["plan"]["decision"]["passes"] == core.PIPELINE
    assert "breaks the hard rules" in t["plan"]["why"]
    assert t["plan"]["decision"]["rulings"] == []
    assert "recovered" not in t["report"]["decision"]["summary"].lower()
    assert t["classify"]["model"]["receipt"]["model"].startswith("nvidia/nemotron")
    assert calls == ["classify", "plan", "report"]


def test_sample_mode_replays_without_files_or_model(env, monkeypatch):
    calls = []
    fake_model(monkeypatch, {"classify": {"items": [], "clipped_items": [], "why": "from rows"}}, calls)
    case = json.load(open("evals/cases/case03_dawn_jungle_match.json"))
    live = core.run_case(case, sample_mode=False, log_path=env / "live.jsonl")
    # Judges' copy: only evidence.json per clip, no images or EXRs, no Nightshift.
    for c in case["clips"]:
        d = samples.SAMPLES_DIR / c
        for f in list(d.iterdir()):
            if f.name != "evidence.json":
                shutil.rmtree(f) if f.is_dir() else f.unlink()
    no_model(monkeypatch)
    replay = core.run_case(case, sample_mode=True, log_path=env / "replay.jsonl")
    assert len(calls) == 3
    pick = lambda out: [(l["step"], l["decision"].get("items"), l["decision"].get("max_lum_gap_stops"),
                         l["cites"]) for l in out["trace"] if l["step"] != "run"]
    assert pick(live) == pick(replay)
    assert replay["trace"][0]["model"]["note"] == "replayed saved answer"


def test_two_clip_gap_before_and_after(env, monkeypatch):
    no_model(monkeypatch)
    out = core.run_case(json.load(open("evals/cases/case03_dawn_jungle_match.json")), False, env / "r.jsonl")
    check = next(l for l in out["trace"] if l["step"] == "verify")["decision"]["checks"][0]
    assert check["gap_before_balance"] == pytest.approx(1.0, abs=0.01)  # jungle clip one stop hot
    assert abs(check["max_lum_gap_stops"]) < core.MAX_GAP_STOPS
    assert check["passed"]


def test_post_run(env, monkeypatch):
    no_model(monkeypatch)
    run.Handler.log_path = str(env / "srv.jsonl")
    srv = HTTPServer(("127.0.0.1", 0), run.Handler)
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    url = f"http://127.0.0.1:{srv.server_port}/run"
    req = urllib.request.Request(url, data=json.dumps({"case": "case01_car_sky"}).encode(),
                                 headers={"Content-Type": "application/json"})
    body = json.loads(urllib.request.urlopen(req).read())
    srv.shutdown()
    assert body["report"]["passed"] is True
    assert [l["step"] for l in body["trace"]] == ["classify", "plan", "run", "verify", "report"]
